"""
Module for validating qBraid environments.

"""

import logging
import re
from dataclasses import dataclass
from enum import Enum
from typing import Optional, Union

logger = logging.getLogger(__name__)


class PlatformCompatibility(Enum):
    """Platform compatibility levels."""

    COMPATIBLE = "compatible"
    EMULATION_WARNING = "emulation_warning"  # Same OS, different arch
    INCOMPATIBLE = "incompatible"  # Different OS
    UNKNOWN = "unknown"  # Missing platform info


@dataclass
class PlatformValidationResult:
    """Result of platform compatibility validation.

    Attributes:
        compatibility: Compatibility level
        is_compatible: Whether environment is expected to work on the target platform.
            True for COMPATIBLE and EMULATION_WARNING (may work).
            False for INCOMPATIBLE (different OS, unlikely to work).
            True for UNKNOWN (benefit of the doubt).
        message: Human-readable explanation
        source_platform: Platform the environment was built for
        target_platform: Current system platform
    """

    compatibility: PlatformCompatibility
    is_compatible: bool
    message: str
    source_platform: Optional[str]
    target_platform: str


def _normalize_platform(platform: Union[str, list, None]) -> Optional[str]:
    """Normalize platform value to standard format.

    Handles various formats from API:
    - String: "linux-x86_64" -> "linux-x86_64"
    - List: ["Linux_x86_64"] -> "linux-x86_64"
    - Underscore format: "Linux_x86_64" -> "linux-x86_64"

    Args:
        platform: Platform value in various formats

    Returns:
        Normalized platform string or None
    """
    if platform is None:
        return None

    # Handle list format from API
    if isinstance(platform, list):
        if not platform:
            return None
        platform = platform[0]

    if not isinstance(platform, str):
        return None

    if not platform:
        return None

    # Normalize to lowercase and replace underscores with hyphens
    # "Linux_x86_64" -> "linux-x86_64"
    normalized = platform.lower()

    # Handle underscore format (Linux_x86_64 -> linux-x86_64)
    # But preserve underscores within arch parts (x86_64 keeps its underscore)
    if "_" in normalized and "-" not in normalized:
        # Split only on FIRST underscore to separate OS from arch
        # "linux_x86_64" -> ["linux", "x86_64"] -> "linux-x86_64"
        parts = normalized.split("_", 1)
        if len(parts) == 2:
            normalized = f"{parts[0]}-{parts[1]}"

    return normalized


def validate_platform_compatibility(
    env_platform: Optional[str],
    current_platform: str,
) -> PlatformValidationResult:
    """Validate if an environment's platform is compatible with current system.

    This function checks if an environment built for one platform can run on
    another. It returns warnings but never blocks - the design decision is to
    warn only, allowing users to proceed.

    Args:
        env_platform: Platform the environment was built for (e.g., "linux-x86_64",
                      "darwin-arm64"). Can be None, a string, or a list (from API).
        current_platform: Current system platform (from get_current_platform())

    Returns:
        PlatformValidationResult with compatibility assessment

    Examples:
        >>> result = validate_platform_compatibility("linux-x86_64", "linux-x86_64")
        >>> result.is_compatible
        True
        >>> result.compatibility
        <PlatformCompatibility.COMPATIBLE: 'compatible'>

        >>> result = validate_platform_compatibility("darwin-arm64", "linux-x86_64")
        >>> result.is_compatible
        False  # Different OS, unlikely to work
        >>> result.compatibility
        <PlatformCompatibility.INCOMPATIBLE: 'incompatible'>
    """
    # Normalize platform values
    env_platform = _normalize_platform(env_platform)

    # Handle unknown/missing platform
    if env_platform is None or env_platform == "":
        return PlatformValidationResult(
            compatibility=PlatformCompatibility.UNKNOWN,
            is_compatible=True,  # Allow with warning
            message="Environment platform is unknown. Compatibility cannot be verified.",
            source_platform=env_platform,
            target_platform=current_platform,
        )

    # Same platform = fully compatible
    if env_platform == current_platform:
        return PlatformValidationResult(
            compatibility=PlatformCompatibility.COMPATIBLE,
            is_compatible=True,
            message=f"Environment is compatible with current platform ({current_platform}).",
            source_platform=env_platform,
            target_platform=current_platform,
        )

    # Parse platforms: format is "os-arch" (e.g., "linux-x86_64", "darwin-arm64")
    try:
        env_os, env_arch = env_platform.rsplit("-", 1)
        current_os, current_arch = current_platform.rsplit("-", 1)
    except ValueError:
        # Invalid platform format
        return PlatformValidationResult(
            compatibility=PlatformCompatibility.UNKNOWN,
            is_compatible=True,
            message=f"Invalid platform format: '{env_platform}'. Proceeding anyway.",
            source_platform=env_platform,
            target_platform=current_platform,
        )

    # Different OS = incompatible (but warn, don't block)
    if env_os != current_os:
        os_names = {"linux": "Linux", "darwin": "macOS", "win32": "Windows"}
        env_os_name = os_names.get(env_os, env_os)
        current_os_name = os_names.get(current_os, current_os)

        return PlatformValidationResult(
            compatibility=PlatformCompatibility.INCOMPATIBLE,
            is_compatible=False,  # Different OS, unlikely to work
            message=(
                f"Environment was built for {env_os_name} ({env_platform}) "
                f"but current system is {current_os_name} ({current_platform}). "
                "The environment will not work on this system."
            ),
            source_platform=env_platform,
            target_platform=current_platform,
        )

    # Same OS, different architecture = may work with emulation
    if env_arch != current_arch:
        # Check for known emulation scenarios
        emulation_note = ""
        if env_os == "darwin":
            if env_arch == "x86_64" and current_arch == "arm64":
                emulation_note = " (Rosetta 2 emulation may be available)"
            elif env_arch == "arm64" and current_arch == "x86_64":
                emulation_note = " (ARM binaries cannot run on Intel without emulation)"
        elif env_os == "linux":
            if env_arch == "x86_64" and current_arch == "arm64":
                emulation_note = " (qemu-user emulation may be available)"

        return PlatformValidationResult(
            compatibility=PlatformCompatibility.EMULATION_WARNING,
            is_compatible=True,
            message=(
                f"Environment was built for {env_arch} architecture "
                f"but current system is {current_arch}.{emulation_note} "
                "The environment may work via emulation but performance may be reduced."
            ),
            source_platform=env_platform,
            target_platform=current_platform,
        )

    # This shouldn't be reached, but handle edge cases
    return PlatformValidationResult(
        compatibility=PlatformCompatibility.UNKNOWN,
        is_compatible=True,
        message="Platform compatibility could not be determined.",
        source_platform=env_platform,
        target_platform=current_platform,
    )


def is_valid_env_name(env_name: str) -> bool:
    """
    Validates an environment display name.

    The name is used for display purposes (UI, CLI listing, kernel name) —
    not as a filesystem path. Directory names are derived separately via
    make_env_dir_name() using the sanitized slug/env_id.

    Allowed: letters, digits, spaces, dashes, underscores, dots,
    parentheses, commas, plus signs, and common version strings
    like "CUDA-Q (v0.14.0)" or "qBraid-SDK v0.9.7".

    Blocked: shell injection characters and control characters.

    Args:
        env_name (str): The environment display name to validate.

    Returns:
        bool: True if the name is valid, False otherwise.
    """
    is_valid = True

    # Basic checks for empty names or purely whitespace names
    if not env_name or not isinstance(env_name, str) or env_name == "" or env_name.isspace():
        is_valid = False

    # Block dangerous shell metacharacters and control characters.
    # Allow: letters, digits, spaces, dashes, underscores, dots,
    # parentheses, commas, plus, at, single quotes, equals
    elif re.search(r'[<>:"/\\|?*&;$\[\]#~!{}`\x00-\x1f]', env_name):
        is_valid = False

    # Reserved names for Windows (example list, can be expanded)
    elif env_name.upper() in [
        "CON",
        "PRN",
        "AUX",
        "NUL",
        "COM1",
        "COM2",
        "COM3",
        "COM4",
        "COM5",
        "COM6",
        "COM7",
        "COM8",
        "COM9",
        "LPT1",
        "LPT2",
        "LPT3",
        "LPT4",
        "LPT5",
        "LPT6",
        "LPT7",
        "LPT8",
        "LPT9",
    ]:
        is_valid = False

    elif len(env_name) > 100:
        is_valid = False

    return is_valid


def is_valid_slug(slug: str) -> bool:
    """Validates whether a slug meets the defined criteria."""
    # Initialize result as False
    result = False

    # Define the length constraints
    max_total_length = 20
    slug_alphanumeric_length = 6
    max_name_part_length = max_total_length - slug_alphanumeric_length - 1

    legacy = ["cirq__openfer_5f52ck"]

    if slug in legacy:
        result = True
    if len(slug) <= max_total_length and slug:
        # Split the slug into name part and alphanumeric part
        parts = slug.rsplit("_", 1)
        if 2 <= len(parts) <= 3 and len(parts[0]) <= max_name_part_length:
            name_part = parts[0]
            alphanumeric_part = parts[-1]

            # Check the alphanumeric and name parts
            if (
                re.fullmatch(r"^[a-z0-9]{6}$", alphanumeric_part)
                and 0 < len(name_part) <= max_name_part_length
                and re.fullmatch(r"^[a-z0-9]+(_[a-z0-9]+)*$", name_part)
            ):
                result = True

    return result


__all__ = [
    "PlatformCompatibility",
    "PlatformValidationResult",
    "validate_platform_compatibility",
    "is_valid_env_name",
    "is_valid_slug",
]
